#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn searches() {
        assert_eq!(
            abbr_search(b"GMT", -1, 0).unwrap().full_tz_name,
            Some("UTC")
        );
        assert_eq!(abbr_search(b"cest", -1, 0).unwrap().gmtoffset, 7200);
        assert_eq!(
            abbr_search(b"EST", -18000, 0).unwrap().full_tz_name,
            Some("America/New_York")
        );
        assert_eq!(
            abbr_search(b"nope", 3600, 0).unwrap().full_tz_name,
            Some("Europe/Paris")
        );
        assert!(abbr_search(b"nope", 1, 0).is_none());
        assert_eq!(timezone_abbreviations_list().len(), 1127);
    }
}
